def bubble_sort(a, key=lambda x: x):
    for end in range(len(a)-1, 0, -1):
        swapped = False
        for j in range(end):
            if key(a[j]) > key(a[j+1]):
                a[j], a[j+1] = a[j+1], a[j]
                swapped = True
        if not swapped:
            break
    return a

def selection_sort(a, key=lambda x: x):
    n = len(a)
    for i in range(n-1):
        m = i
        for j in range(i+1, n):
            if key(a[j]) < key(a[m]):
                m = j
        if m != i:
            a[i], a[m] = a[m], a[i]
    return a

def insertion_sort(a, key=lambda x: x):
    for j in range(1, len(a)):
        saved = a[j]
        saved_key = key(saved)
        i = j-1
        while i >= 0 and key(a[i]) > saved_key:
            a[i+1] = a[i]
            i -= 1
        a[i+1] = saved
    return a

